/**
 * Generates supabase/seed.sql from the static configuration in src/config.
 *
 *   npm run db:seed:generate
 *
 * The seed copies the CURRENT website content into the database so nothing is lost when the site
 * switches to database-driven content. It states only what the config already states: empty
 * values stay empty (no contact details, social profiles, mission, vision, registration numbers,
 * prices or testimonials are invented). Re-running the generated file is safe (upserts).
 */
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { categories, products } from "../src/config/products";
import { services, processSteps } from "../src/config/services";
import { industries } from "../src/config/industries";
import { documents } from "../src/config/documents";
import { photos, productPhotos } from "../src/config/images";
import { site } from "../src/config/site";

const q = (v: string | null | undefined): string => (v == null ? "null" : `'${String(v).replace(/'/g, "''")}'`);
const b = (v: boolean) => (v ? "true" : "false");
const out: string[] = [];
const push = (s = "") => out.push(s);

push("-- GENERATED by scripts/generate-seed.ts from src/config. Do not edit by hand; re-generate instead.");
push("-- Idempotent: safe to run more than once. Admin edits made after seeding are NOT overwritten");
push("-- for singleton rows (company_settings, homepage_settings use ON CONFLICT DO NOTHING).");
push("begin;");
push();

// Company + homepage singletons
push("insert into public.company_settings (id, registered_name, brand_name, tagline, promise, description, city, country, service_coverage, footer_text)");
push(`values (1, ${q(site.legalName)}, ${q(site.name)}, ${q(site.tagline)}, ${q(site.promise)}, ${q(site.description)}, 'Nairobi', 'Kenya', ${q(site.serviceLocation)}, null)`);
push("on conflict (id) do nothing;");
push();
push("insert into public.homepage_settings (id, headline, subheadline, primary_cta_label, primary_cta_href, secondary_cta_label, secondary_cta_href, services_heading, industries_heading, products_heading)");
push(`values (1, ${q(site.headline)}, ${q(site.heroText)}, 'Request a Quote', '/quote', 'Explore Our Products', '/products', 'From requirement to receiving bay', 'Industries we serve', 'What we supply')`);
push("on conflict (id) do nothing;");
push();

// Categories
categories.forEach((c, i) => {
  const img = photos[c.slug];
  push(
    "insert into public.product_categories (slug, name, summary, icon, seo_description, fallback_image, image_alt, sort_order, is_active) " +
      `values (${q(c.slug)}, ${q(c.name)}, ${q(c.summary)}, ${q(c.icon)}, ${q(c.seoDescription)}, ${q(img?.src)}, ${q(img?.alt)}, ${(i + 1) * 10}, true) ` +
      "on conflict (slug) do nothing;",
  );
});
push();

// Products + specifications
products.forEach((p, i) => {
  const photo = productPhotos[p.slug] ?? photos[p.category];
  push(
    "insert into public.products (slug, name, category_id, summary, description, fallback_image, image_alt, packaging, status, sort_order) " +
      `values (${q(p.slug)}, ${q(p.name)}, (select id from public.product_categories where slug = ${q(p.category)}), ${q(p.description)}, ${q(p.description)}, ${q(photo?.src)}, ${q(photo?.alt)}, ${q(p.packaging)}, 'published', ${(i + 1) * 10}) ` +
      "on conflict (slug) do nothing;",
  );
  p.specs.forEach((s, j) => {
    push(
      "insert into public.product_specifications (product_id, label, value, sort_order) " +
        `select id, ${q(s.label)}, ${q(s.value)}, ${(j + 1) * 10} from public.products where slug = ${q(p.slug)} ` +
        `and not exists (select 1 from public.product_specifications x where x.product_id = products.id and x.label = ${q(s.label)});`,
    );
  });
});
push();

// Services
services.forEach((s, i) => {
  push(
    "insert into public.services (slug, title, summary, description, icon, is_featured, sort_order, is_active) " +
      `values (${q(s.slug)}, ${q(s.title)}, ${q(s.summary)}, ${q(s.detail)}, ${q(s.icon)}, true, ${(i + 1) * 10}, true) on conflict (slug) do nothing;`,
  );
});
push();

// Industries (+ needs + category links)
industries.forEach((ind, i) => {
  push(
    "insert into public.industries (slug, title, summary, icon, is_featured, sort_order, is_active) " +
      `values (${q(ind.slug)}, ${q(ind.name)}, ${q(ind.summary)}, null, true, ${(i + 1) * 10}, true) on conflict (slug) do nothing;`,
  );
  ind.needs.forEach((n, j) => {
    push(
      "insert into public.industry_needs (industry_id, text, sort_order) " +
        `select id, ${q(n)}, ${(j + 1) * 10} from public.industries where slug = ${q(ind.slug)} ` +
        `and not exists (select 1 from public.industry_needs x where x.industry_id = industries.id and x.text = ${q(n)});`,
    );
  });
  ind.categories.forEach((c, j) => {
    push(
      "insert into public.industry_categories (industry_id, category_id, sort_order) " +
        `select i.id, c.id, ${(j + 1) * 10} from public.industries i, public.product_categories c where i.slug = ${q(ind.slug)} and c.slug = ${q(c)} on conflict do nothing;`,
    );
  });
});
push();

// Process steps (no natural key: only seed when the table is empty)
push("insert into public.process_steps (title, body, sort_order)");
push("select * from (values");
push(processSteps.map((s, i) => `  (${q(s.title)}, ${q(s.text)}, ${(i + 1) * 10})`).join(",\n"));
push(") as v(title, body, sort_order) where not exists (select 1 from public.process_steps);");
push();

// Documents (no files until the owner approves them)
push("insert into public.site_documents (title, description, sort_order)");
push("select * from (values");
push(documents.map((d, i) => `  (${q(d.title)}, ${q(d.description)}, ${(i + 1) * 10})`).join(",\n"));
push(") as v(title, description, sort_order) where not exists (select 1 from public.site_documents);");
push();
push("commit;");

const file = resolve(__dirname, "../supabase/seed.sql");
writeFileSync(file, out.join("\n") + "\n");
console.log(`Wrote ${file}: ${categories.length} categories, ${products.length} products, ${services.length} services, ${industries.length} industries.`);
